INSERT INTO `email_templates` VALUES (1,'welcome','Welcome to Boutique','<div style=\"font-family:sans-serif;line-height:1.6;color:#111827;\"><h2>Welcome, {{customer_name}}</h2><p>Thank you for joining our community of mindful living. Your account is ready.</p></div>',1,'2026-10-12 05:21:07','2026-10-12 05:21:07'),(2,'order_confirmation','Order Confirmation #{{order_number}}','<div style=\"font-family:sans-serif;line-height:1.6;color:#111827;\"><h2>Thank you for your order, {{customer_name}}!</h2><p>We are preparing your items with care. Your order number is <strong>#{{order_number}}</strong>.</p><p>Total: {{order_total}}</p></div>',1,'2026-10-12 05:21:07','2026-10-12 05:21:07'),(3,'order_shipped','Your order #{{order_number}} is on its way','<div style=\"font-family:sans-serif;line-height:1.6;color:#111827;\"><h2>Your package has shipped</h2><p>Track your shipment here: <a href=\"{{tracking_link}}\">{{tracking_number}}</a></p></div>',1,'2026-10-12 05:21:07','2026-10-12 05:21:07'),(4,'password_reset','Reset Your Boutique Password','<div style=\"font-family:sans-serif;line-height:1.6;color:#111827;\"><h2>Password Reset Request</h2><p>Click below to securely reset your password:</p><p><a href=\"{{reset_url}}\">Reset Password</a></p></div>',1,'2026-10-12 05:21:07','2026-10-12 05:21:07'),(5,'new_order_admin','New Order Alert #{{order_number}}','<div style=\"font-family:sans-serif;line-height:1.6;color:#111827;\"><h2>New Order Received</h2><p>Order #{{order_number}} from {{customer_email}} totaling {{order_total}}.</p></div>',1,'2026-10-12 05:21:07','2026-10-12 05:21:07');
/*!40000 ALTER TABLE `email_templates` ENABLE KEYS */;
