INSERT INTO `hero_slides` VALUES (1,'Mindfully Crafted Goods','Minimalist apparel and everyday homeware designed to outlast fleeting trends.','Explore Collection','/shop','https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=1600&q=80','https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=800&q=80','left',0.25,1,1,NULL,NULL,'2026-10-12 05:21:07','2026-10-12 05:21:07'),(2,'Pure Organic Linen','Breathable, tactile textures tailored for effortless daily comfort.','Shop Apparel','/category/apparel','https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=1600&q=80','https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=800&q=80','left',0.25,2,1,NULL,NULL,'2026-10-12 05:21:07','2026-10-12 05:21:07'),(3,'Tactile Ceramic Objects','Wheel-thrown stoneware and artisanal lighting to ground your living sanctuary.','Discover Homeware','/category/home-living','https://images.unsplash.com/photo-1616046229478-9901c5536a45?auto=format&fit=crop&w=1600&q=80','https://images.unsplash.com/photo-1616046229478-9901c5536a45?auto=format&fit=crop&w=800&q=80','center',0.20,3,1,NULL,NULL,'2026-10-12 05:21:07','2026-10-12 05:21:07');
