/*!40000 ALTER TABLE `pages` DISABLE KEYS */;
INSERT INTO `pages` VALUES (1,'About Our Studio','about','<h2>Mindful Design for Daily Living</h2><p>Founded on principles of calm proportion, durable utility, and sustainable sourcing, Boutique collaborates directly with independent artisans across Europe and Japan. We prioritize timeless materials over seasonal cycles.</p>',1,'About Our Studio | Boutique','Discover our philosophy of thoughtful craftsmanship, honest materials, and sustainable design.','2026-10-12 05:21:07','2026-10-12 05:21:07'),(2,'Frequently Asked Questions','faq','<h2>Common Questions</h2><p><strong>Where do you manufacture?</strong> Our ceramic, linen, and leather goods are made in small workshops in Portugal, Spain, and Japan.</p><p><strong>How long does shipping take?</strong> Domestic orders arrive within 2–4 business days with carbon-neutral transit.</p>',1,'FAQ | Boutique Customer Care','Answers to questions regarding shipping, returns, sustainability, and product care.','2026-10-12 05:21:07','2026-10-12 05:21:07'),(3,'Shipping & Delivery','shipping','<h2>Domestic & International Shipping</h2><p>All items are carefully packaged in 100% recyclable, plastic-free boxes. Orders placed before 1 PM EST are dispatched the same business day.</p>',1,'Shipping & Delivery Information | Boutique','Reliable, carbon-neutral shipping rates and estimated delivery timelines.','2026-10-12 05:21:07','2026-10-12 05:21:07'),(4,'Returns & Guarantee','returns','<h2>Hassle-Free 30-Day Returns</h2><p>If you are not thoroughly satisfied with your purchase, you may initiate a return within 30 days of receipt in original, unworn condition.</p>',1,'Returns & Guarantee Policy | Boutique','Simple 30-day returns and store warranty details.','2026-10-12 05:21:07','2026-10-12 05:21:07'),(5,'Privacy Policy','privacy','<h2>Your Privacy Matters</h2><p>We respect your personal data and never sell or distribute your contact details to third parties. We strictly use cookies to enable secure sessions and optimize website speed.</p>',1,'Privacy Policy | Boutique','Our commitment to data privacy, secure cookie handling, and encrypted payment processing.','2026-10-12 05:21:07','2026-10-12 05:21:07'),(6,'Terms of Service','terms','<h2>Terms & Conditions</h2><p>By using Boutique, you agree to fair use, honest interactions, and standard commercial conditions under governing consumer protections.</p>',1,'Terms of Service | Boutique','Store terms of service, payment guarantees, and customer rights.','2026-10-12 05:21:07','2026-10-12 05:21:07');
/*!40000 ALTER TABLE `pages` ENABLE KEYS */;
UNLOCK TABLES;

