INSERT INTO `reviews` VALUES (1,1,4,'Claire Henderson',NULL,5,'Exceptional build quality','The tactile feel and finish exceeded my expectations. Arrived in plastic-free packaging within three days.',1,0,NULL,'2026-09-27 05:21:07',18,'2026-10-12 05:21:07','2026-10-12 22:17:26'),(2,2,4,'Marcus Thorne',NULL,5,'A calm and beautiful daily essential','Exactly as described. Subtle color, clean seams, and feels substantial in hand.',1,0,NULL,'2026-09-06 05:21:07',1,'2026-10-12 05:21:07','2026-10-12 05:21:07'),(3,3,4,'Avery Brooks',NULL,4,'Worth every penny','You can genuinely tell the difference in craftsmanship compared to generic department store alternatives.',1,0,NULL,'2026-09-03 05:21:07',4,'2026-10-12 05:21:07','2026-10-12 05:21:07'),(4,4,4,'Elena Vance',NULL,4,'Understated elegance','Minimalist design that fits into our home effortlessly. Very happy with this purchase.',1,0,NULL,'2026-09-22 05:21:07',5,'2026-10-12 05:21:07','2026-10-12 05:21:07'),(5,5,4,'Julian Hayes',NULL,4,'Sturdy and well-proportioned','Delivered promptly and looks gorgeous on the counter. Would happily recommend.',1,0,NULL,'2026-09-10 05:21:07',6,'2026-10-12 05:21:07','2026-10-12 05:21:07'),(6,6,4,'Sora Tanaka',NULL,4,'Thoughtful packaging and great texture','The natural material feels soft yet durable. Has held up beautifully after everyday use.',1,0,NULL,'2026-09-09 05:21:07',12,'2026-10-12 05:21:07','2026-10-12 05:21:07'),(7,7,4,'David Miller',NULL,4,'My new favourite piece','Subtle styling and great attention to detail. Excellent customer care as well.',1,0,NULL,'2026-09-17 05:21:07',11,'2026-10-12 05:21:07','2026-10-12 05:21:07'),(8,8,4,'Hannah Lindqvist',NULL,4,'High quality and prompt shipping','Great experience ordering here. Everything was seamless from checkout to unboxing.',1,0,NULL,'2026-09-19 05:21:07',12,'2026-10-12 05:21:07','2026-10-12 05:21:07'),(9,9,4,'Claire Henderson',NULL,4,'Exceptional build quality','The tactile feel and finish exceeded my expectations. Arrived in plastic-f